SELECT t.id, t.task_type AS "taskType", t.project_id AS "projectId", t.status, t.progress, t.current_step AS "currentStep", t.error_message AS "errorMessage", t.token_usage AS "tokenUsage", t.created_at AS "createdAt", t.updated_at AS "updatedAt", p.title AS "projectTitle", p.created_by AS "createdBy", u.username AS "creatorUsername" FROM story_generation_task t LEFT JOIN story_project p ON p.id = t.project_id LEFT JOIN biz_user_account u ON u.user_id = p.created_by
t.status = #{status}
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}
